// === Tab: mySketch ===
/* jacques maire;
* fork timtim "https://openprocessing.org/sketch/1116844"
* test shader 3D
*/

p5.disableFriendlyErrors = true

let myShader;

function preload() {

  myShader = createShader(vert, frag);
}

function setup() {
  createCanvas(1112, 834, WEBGL);
  noStroke();
}

function draw() {
  background(0);
  shader(myShader);
  myShader.setUniform("uFrameCount", frameCount*2);

  rotateX(frameCount * 0.001);
  rotateY(frameCount * 0.001);
  translate(2.0*cos(frameCount * 0.01),2.0*sin(frameCount * 0.01),200.0);
  // Draw some geometry to the screen

  sphere(width / 2.0, 700.0, 100.0);
}

function windowResized() {
  resizeCanvas(1112, 834);
}

// === Tab: tab2 ===
vert=`
// Obtenez l’attribut de position de la géométrie
attribute vec3 aPosition;

// Obtenez l’attribut de coordination de texture de la géométrie
attribute vec2 aTexCoord;

// Obtenez l’attribut vertéx normal de la géométrie
attribute vec3 aNormal;

//Lorsque nous utilisons la géométrie 3D, nous devons également utiliser certaines variables intégrées que p5 fournit
// La plupart des moteurs 3D vous fourniront ces variables. Ce sont des matrices 4x4 qui définissent
// the camera position / rotation, and the geometry position / rotation / scale
// Il ya en fait 3 matrices, mais deux d’entre eux ont déjà été combinés en un seul
// Cette pré-combinaison est un truc d’optimisation de sorte que l’ombrage vertex n’a pas à faire autant de travail

// uProjectionMatrix est utilisé pour convertir les coordonnées globale 3D en coordonnées d’écran 2D
uniform mat4 uProjectionMatrix;

// uModelViewMatrix est une combinaison de la matrice du modèle et de la matrice de vue
// The model matrix defines the object position / rotation / scale
// Multiplier uModelMatrix * vec4 (aPosition, 1.0) déplacerait l’objet dans sa position mondiale

// The view matrix defines attributes about the camera, such as focal length and camera position
// Multiplying uModelViewMatrix * vec4(aPosition, 1.0) would move the object into its world position in front of the camera
uniform mat4 uModelViewMatrix;

//  Obtenez l’uniforme framecount
uniform float uFrameCount;

varying vec2 vTexCoord;
varying vec3 vNormal;
vec4 quaternion(vec3 axis, float phi){
 vec3 axs=normalize(axis);
  return vec4(axs*sin(phi/2.0),cos(phi/2.0));}

vec3 qtourne(vec4 q, vec3 v){return v+2.0*cross(cross(v,q.xyz)-(q.w)*v,q.xyz);}



void main() {

  // copier les données de position dans un vec4, en utilisant 1.0 comme composant w
  vec4 positionVec4 = vec4(aPosition, 4.0);
   vec3  axv         =normalize(vec3(0.0,uFrameCount,0.0)*3.0);
   vec4 qua= quaternion(axv,cos(positionVec4.x) );
   vec3 tou=qtourne(qua,aNormal*3.0);
  tou+=aPosition;
  // La fréquence et l’amplitude détermineront l’apparence du déplacement
  float frequency = 5.5;
  float amplitude = 5.0;
  float distortion = sin(positionVec4.x * frequency + uFrameCount * 0.02);
  positionVec4.x *= distortion * aNormal.x * amplitude*0.6;


  vNormal = aNormal;
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
  vTexCoord = aTexCoord;
}`;

// === Tab: tab3 ===
frag=`

precision mediump float;

varying vec2 vTexCoord;
varying vec3 vNormal;

void main() {
  vec3 color = vNormal*3.2  ;
  gl_FragColor = vec4(color ,1.0);
}`;

